import type { ComponentProps } from 'react';

export type RoxyHdPentaProps = ComponentProps<typeof Element>;

export function RoxyHdPenta(props: RoxyHdPentaProps) {
	return <Element {...props} />;
}

export default RoxyHdPenta;
